PRAGMA journal_mode=WAL;
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE chat_threads(id TEXT NOT NULL PRIMARY KEY, title TEXT NOT NULL, model_type TEXT NOT NULL, model_id TEXT, created_at INTEGER NOT NULL, forked_from_thread_id TEXT);
CREATE TABLE chat_messages(id TEXT NOT NULL PRIMARY KEY, thread_id TEXT NOT NULL REFERENCES chat_threads(id) ON DELETE CASCADE, parent_id TEXT, role TEXT NOT NULL, content_json TEXT NOT NULL, metadata_json TEXT, created_at INTEGER NOT NULL);
CREATE TABLE api_usage_events(id TEXT NOT NULL PRIMARY KEY, subject TEXT NOT NULL, model TEXT NOT NULL, prompt_tokens INTEGER NOT NULL, completion_tokens INTEGER NOT NULL, total_tokens INTEGER NOT NULL, created_at INTEGER NOT NULL) WITHOUT ROWID;
COMMIT;
